import assert from "node:assert/strict";
import {readFileSync} from "node:fs";
import {HOLY_CLOAK_SOURCE_ACCESS_V1 as w,holyCloakSourceMatches} from "../src/pray/holy-cloak-source-access.v1.js";
assert.equal(w.id,"st_joseph_holy_cloak_30_days");
assert.equal(w.subject,"VI");
assert.deepEqual(w.schedule,{dayCount:30,sameCompleteDailyForm:true,distinctDailyPrayers:0});
assert.equal(w.primary.language,"en");
assert.equal(w.primary.form,"FIVE_SECTION_ENGLISH_PRESENTATION");
assert.match(w.primary.url,/^https:\/\/mhocsa\.org\.au\/holy-cloak-of-st-joseph\/$/);
assert.equal(w.otherWitnesses.length,2);
assert.equal(w.otherWitnesses[0].form,"SIX_SECTION_ENGLISH_PRESENTATION_WITH_ADDITIONAL_CLOSING_PRAYER");
assert.equal(w.otherWitnesses[1].form,"CLAIMED_1882_ITALIAN_NINETEEN_NUMBERED_PASSAGES_WITH_IMAGE_ONLY_TEXT");
assert.equal(w.nativePrayerTextIncluded,false);
assert.equal(w.frenchPrayerTextIncluded,false);
assert.equal(w.originalItalianPrintCertified,false);
assert.equal(w.historicalIndulgencesCurrent,false);
for(const q of ["holy cloak","sacro manto","manteau de saint joseph","thirty days"])
 assert.ok(holyCloakSourceMatches({search:q,subject:"VI"}),q);
assert.equal(holyCloakSourceMatches({search:"holy cloak",subject:"V"}),false);
assert.equal(holyCloakSourceMatches({search:"holy cloak",subject:"VI",category:"essentials"}),false);
assert.equal(holyCloakSourceMatches({search:"not a matching prayer",subject:"VI"}),false);
const ui=readFileSync(new URL("../src/pray/presentation-runtime.js",import.meta.url),"utf8");
assert.match(ui,/holyCloakSourceMatches\(\{search:q,subject:LIB\.subject,category:LIB\.cat\}\)/);
assert.match(ui,/data-ao-holy-cloak-source-only/);
assert.match(ui,/data-ao-holy-cloak-source-link/);
assert.match(ui,/rel="noopener noreferrer"/);
assert.match(ui,/not yet an offline in-app reader/);
assert.match(ui,/ni la traduction française ni l’édition exacte de 1882/);
assert.match(ui,/\$\{massSequenceSection\}\$\{holyCloakSection\}\$\{guidedSection\}/);
const sourceModule=readFileSync(new URL("../src/pray/holy-cloak-source-access.v1.js",import.meta.url),"utf8");
assert.doesNotMatch(sourceModule,/Offering I:|Prayer I: Hail|Holy Mary, pray for us/,"No copied modern prayer bodies in source-access module");
assert.doesNotMatch(ui,/data-ao-holy-cloak-source-link[^;]*data-p435930-lib-open/,"External source must not claim native canonical card");
console.log("Holy Cloak: complete English external Catholic parish source linked; 30 same-form days; 1882 Italian and 6-section variants held; no copied text or invented FR PASS");
